class Base {
  #i() { return 'B.i'; }
  #x = 'B.x';
  base(): string { return this.#i() + this.#x; }
}
class Derived extends Base {
  #i() { return 'D.i'; }
  #x = 'D.x';
  derived(): string { return this.#i() + this.#x; }
}
function main() {
  const d = new Derived();
  console.log(d.derived(), d.base());
}
